import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

reductions_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void min_dim2_kernel(const float* in, float* out, int N, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx < total) {
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int c_idx = (idx / (W * H)) % C;
        int n_idx = idx / (W * H * C);

        float min_val = in[n_idx * C * D * H * W + c_idx * D * H * W + 0 * H * W + h_idx * W + w_idx];
        for (int d = 1; d < D; d++) {
            float val = in[n_idx * C * D * H * W + c_idx * D * H * W + d * H * W + h_idx * W + w_idx];
            if (val < min_val) {
                min_val = val;
            }
        }
        out[idx] = min_val;
    }
}

__global__ void softmax_dim1_kernel(const float* in, float* out, int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * H * W;
    if (idx < total) {
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int n_idx = idx / (W * H);

        // Find max for numerical stability
        float max_val = -1e30f;
        for (int c = 0; c < C; c++) {
            float val = in[n_idx * C * H * W + c * H * W + h_idx * W + w_idx];
            if (val > max_val) {
                max_val = val;
            }
        }

        // Sum exp
        float sum_exp = 0.0f;
        for (int c = 0; c < C; c++) {
            float val = in[n_idx * C * H * W + c * H * W + h_idx * W + w_idx];
            sum_exp += expf(val - max_val);
        }

        // Write normalized
        for (int c = 0; c < C; c++) {
            float val = in[n_idx * C * H * W + c * H * W + h_idx * W + w_idx];
            out[n_idx * C * H * W + c * H * W + h_idx * W + w_idx] = expf(val - max_val) / sum_exp;
        }
    }
}

torch::Tensor min_dim2_cuda(torch::Tensor input) {
    auto sizes = input.sizes(); // [N, C, D, H, W]
    int N = sizes[0];
    int C = sizes[1];
    int D = sizes[2];
    int H = sizes[3];
    int W = sizes[4];

    auto out = torch::zeros({N, C, H, W}, input.options());
    int total = N * C * H * W;
    int block = 256;
    int grid = (total + block - 1) / block;

    min_dim2_kernel<<<grid, block>>>(input.data_ptr<float>(), out.data_ptr<float>(), N, C, D, H, W);
    return out;
}

torch::Tensor softmax_dim1_cuda(torch::Tensor input) {
    auto sizes = input.sizes(); // [N, C, H, W]
    int N = sizes[0];
    int C = sizes[1];
    int H = sizes[2];
    int W = sizes[3];

    auto out = torch::zeros_like(input);
    int total = N * H * W;
    int block = 256;
    int grid = (total + block - 1) / block;

    softmax_dim1_kernel<<<grid, block>>>(input.data_ptr<float>(), out.data_ptr<float>(), N, C, H, W);
    return out;
}
"""

reductions_cpp_source = r"""
torch::Tensor min_dim2_cuda(torch::Tensor input);
torch::Tensor softmax_dim1_cuda(torch::Tensor input);
"""

reductions = load_inline(
    name="reductions",
    cpp_sources=reductions_cpp_source,
    cuda_sources=reductions_source,
    functions=["min_dim2_cuda", "softmax_dim1_cuda"],
    verbose=False
)


class ModelNew(nn.Module):
    """
    Optimized model that replaces torch.min(dim=2) and softmax(dim=1)
    with custom CUDA kernels.
    """
    def __init__(self, in_channels, out_channels, kernel_size, dim):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.dim = dim  # expecting dim=2 for the reduction
        self.reductions = reductions

    def forward(self, x):
        x = self.conv(x)
        # Replace torch.min(..., dim=2)[0]
        x = self.reductions.min_dim2_cuda(x)
        # Replace torch.softmax(..., dim=1)
        x = self.reductions.softmax_dim1_cuda(x)
        return x
